input.content:
/* ==========================================================================
   Relay — operations control room
   Design tokens: restrained neutral surface stack + one purposeful accent.
   Density target: 13px base, 4px spacing scale, tabular numerics everywhere.
   ========================================================================== */

:root {
  --bg:            #0d1015;
  --surface:       #131821;
  --surface-2:     #182029;
  --surface-3:     #1d2732;
  --line:          #232d38;
  --line-strong:   #31404f;

  --text:          #e6eaf0;
  --text-dim:      #99a6b6;
  --text-faint:    #6c7a8b;

  --accent:        #2dd4bf;
  --accent-soft:   rgba(45, 212, 191, 0.12);
  --accent-line:   rgba(45, 212, 191, 0.42);
  --accent-ink:    #04211d;

  --crit:          #f2555a;
  --high:          #f0913c;
  --med:           #dfbb45;
  --low:           #7f8fa6;
  --ok:            #43c08a;

  --radius:        3px;
  --radius-lg:     5px;

  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --rail-w: 208px;
  --detail-w: 356px;
  --topbar-h: 52px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 400 13px/1.45 var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, p, ul, ol, figure { margin: 0; }
ul, ol { padding: 0; list-style: none; }
button, input, select { font: inherit; color: inherit; }

/* Numeric alignment: every figure on the page uses tabular mono. */
.num, .num-col, .metric__value, .clock, kbd, .metric__delta { font-family: var(--mono); font-variant-numeric: tabular-nums; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 8px; top: -48px; z-index: 60;
  background: var(--accent); color: var(--accent-ink);
  padding: 8px 12px; border-radius: var(--radius); font-weight: 600; text-decoration: none;
  transition: top 120ms ease;
}
.skip-link:focus { top: 8px; }

/* Focus: one consistent, always-visible ring. */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}
.rail__link:focus-visible, .th-btn:focus-visible, .chip:focus-visible { outline-offset: -2px; }

/* ── Shell ─────────────────────────────────────────────────────────────── */

.app {
  display: grid;
  grid-template-columns: var(--rail-w) minmax(0, 1fr) var(--detail-w);
  grid-template-rows: var(--topbar-h) minmax(0, 1fr);
  grid-template-areas:
    "rail topbar topbar"
    "rail main   detail";
  height: 100vh;
  height: 100dvh;
}

.rail   { grid-area: rail; }
.topbar { grid-area: topbar; }
.main   { grid-area: main; overflow-y: auto; min-width: 0; }
.detail { grid-area: detail; overflow-y: auto; min-width: 0; }
.main:focus, .detail:focus { outline: none; }

/* ── Navigation rail ───────────────────────────────────────────────────── */

.rail {
  display: flex; flex-direction: column;
  background: var(--surface);
  border-right: 1px solid var(--line);
  padding: 12px 10px;
  min-width: 0;
}

.rail__brand { display: flex; align-items: center; gap: 8px; padding: 4px 6px 14px; }
.rail__mark { color: var(--accent); display: grid; place-items: center; }
.rail__wordmark { font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; font-size: 12px; }

.rail__nav { display: flex; flex-direction: column; gap: 1px; }

.rail__link {
  display: flex; align-items: center; gap: 9px;
  padding: 7px 8px;
  border-radius: var(--radius);
  color: var(--text-dim);
  text-decoration: none;
  font-size: 12.5px;
  border: 1px solid transparent;
}
.rail__link:hover { background: var(--surface-2); color: var(--text); }
.rail__link.is-current {
  background: var(--accent-soft);
  border-color: var(--accent-line);
  color: var(--text);
  font-weight: 550;
}
.rail__ico { display: grid; place-items: center; color: currentColor; opacity: 0.85; }
.rail__link.is-current .rail__ico { color: var(--accent); opacity: 1; }

.rail__count {
  margin-left: auto;
  font-family: var(--mono); font-variant-numeric: tabular-nums;
  font-size: 11px; color: var(--text-faint);
  background: var(--surface-3); border-radius: 10px; padding: 1px 6px;
}
.rail__count:empty { display: none; }

.rail__foot { margin-top: auto; padding: 10px 8px 2px; border-top: 1px solid var(--line); }
.rail__shiftlabel { display: block; font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); }
.rail__shiftname { display: block; font-size: 12px; color: var(--text-dim); margin-top: 3px; }
.rail__hint { margin-top: 10px; font-size: 11px; color: var(--text-faint); line-height: 1.6; }

kbd {
  font-size: 10.5px; background: var(--surface-3); border: 1px solid var(--line-strong);
  border-bottom-width: 2px; border-radius: 3px; padding: 0 3px; color: var(--text-dim);
}

/* ── Top status bar ────────────────────────────────────────────────────── */

.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 0 14px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  min-width: 0;
}
.topbar__left { display: flex; align-items: center; gap: 12px; min-width: 0; }
.topbar__title {
  font-size: 13px; font-weight: 600; letter-spacing: 0.01em;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.topbar__meta { font-size: 11.5px; color: var(--text-faint); font-family: var(--mono); white-space: nowrap; }

.topbar__right { display: flex; align-items: center; gap: 10px; min-width: 0; }

.pill {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11px; font-weight: 550; letter-spacing: 0.02em;
  padding: 2px 8px; border-radius: 999px;
  border: 1px solid var(--line-strong); background: var(--surface-2); color: var(--text-dim);
  white-space: nowrap;
}
.pill--degraded { border-color: rgba(240, 145, 60, 0.4); background: rgba(240, 145, 60, 0.1); color: #f0a463; }
.pill--ok { border-color: rgba(67, 192, 138, 0.4); background: rgba(67, 192, 138, 0.1); color: #67cfa1; }

.dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.dot--degraded { background: var(--high); }
.dot--live { background: var(--ok); animation: pulse 2.4s ease-in-out infinite; }
.dot--paused { background: var(--text-faint); animation: none; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@media (prefers-reduced-motion: reduce) { .dot--live { animation: none; } }

.search { position: relative; display: flex; align-items: center; min-width: 0; }
.search__ico { position: absolute; left: 8px; color: var(--text-faint); display: grid; place-items: center; pointer-events: none; }
.search__input {
  width: 220px; max-width: 34vw;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 6px 8px 6px 26px;
  font-size: 12.5px;
}
.search__input::placeholder { color: var(--text-faint); }
.search__input:hover { border-color: var(--line-strong); }
.search__input:focus-visible { border-color: var(--accent-line); }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  border-radius: var(--radius);
  border: 1px solid var(--line-strong);
  background: var(--surface-2);
  color: var(--text);
  padding: 6px 11px;
  font-size: 12.5px; font-weight: 550;
  cursor: pointer;
  white-space: nowrap;
}
.btn:hover { background: var(--surface-3); border-color: #3b4a5c; }
.btn:active { transform: translateY(0.5px); }
.btn--primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn--primary:hover { background: #45e0cb; border-color: #45e0cb; }
.btn--secondary { background: transparent; }
.btn--ghost { background: transparent; color: var(--text-dim); }
.btn--ghost:hover { color: var(--text); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn:disabled:hover { background: var(--surface-2); }

.clock { display: flex; align-items: baseline; gap: 4px; font-size: 12px; color: var(--text-dim); white-space: nowrap; }
.clock__zone { font-size: 10px; color: var(--text-faint); letter-spacing: 0.06em; }

.who { display: flex; align-items: center; gap: 7px; padding-left: 10px; border-left: 1px solid var(--line); }
.avatar {
  width: 24px; height: 24px; border-radius: 50%;
  display: grid; place-items: center;
  background: var(--surface-3); border: 1px solid var(--line-strong);
  font-size: 10.5px; font-weight: 650; color: var(--text-dim);
}
.who__name { font-size: 12px; color: var(--text-dim); white-space: nowrap; }

/* ── Main column ───────────────────────────────────────────────────────── */

.main { padding: 14px 16px 28px; display: flex; flex-direction: column; gap: 14px; }

.section-h {
  font-size: 11px; font-weight: 600;
  letter-spacing: 0.09em; text-transform: uppercase;
  color: var(--text-faint);
}
.panel__sub { font-size: 11.5px; color: var(--text-faint); margin-top: 3px; }

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 12px 14px 14px;
  min-width: 0;
}
.panel__head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

/* ── Metrics ───────────────────────────────────────────────────────────── */

.metrics__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.metric {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  border-left: 2px solid var(--line-strong);
  padding: 10px 12px 11px;
  min-width: 0;
}
.metric--good { border-left-color: rgba(67, 192, 138, 0.55); }
.metric--bad  { border-left-color: rgba(242, 85, 90, 0.6); }
.metric--flat { border-left-color: var(--line-strong); }

.metric__label {
  font-size: 11px; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--text-faint);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.metric__value {
  font-size: 21px; line-height: 1.15; font-weight: 600;
  margin-top: 6px; letter-spacing: -0.01em;
}
.metric__foot { display: flex; align-items: baseline; gap: 6px; margin-top: 4px; flex-wrap: wrap; }
.metric__delta { font-size: 11.5px; font-weight: 550; display: inline-flex; align-items: center; gap: 3px; }
.metric__delta--good { color: #67cfa1; }
.metric__delta--bad  { color: #f0747a; }
.metric__delta--flat { color: var(--text-faint); }
.metric__ctx { font-size: 11px; color: var(--text-faint); }
.metric__arrow { font-size: 9px; }

/* ── Throughput chart ──────────────────────────────────────────────────── */

.chart { position: relative; min-width: 0; }
.chart__plot svg { display: block; width: 100%; height: auto; }

.chart__bar { fill: #35485c; transition: fill 90ms linear; }
.chart__bar--peak { fill: var(--accent); }
.chart__hit { fill: transparent; cursor: crosshair; }
.chart__hit:hover + .chart__bar,
.chart__hit:focus-visible + .chart__bar { fill: var(--accent); }
.chart__hit:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

.chart__grid { stroke: var(--line); stroke-width: 1; shape-rendering: crispEdges; }
.chart__axis { stroke: var(--line-strong); stroke-width: 1; shape-rendering: crispEdges; }
.chart__tick { fill: var(--text-faint); font: 10px var(--mono); }
.chart__now { stroke: var(--accent-line); stroke-width: 1; stroke-dasharray: 2 3; }

.chart__legend { display: flex; gap: 12px; align-items: center; }
.legend__item { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; color: var(--text-faint); }
.swatch { width: 9px; height: 9px; border-radius: 2px; display: inline-block; }
.swatch--base { background: #35485c; }
.swatch--peak { background: var(--accent); }

.chart__tip {
  position: absolute; z-index: 20;
  transform: translate(-50%, -100%);
  background: var(--surface-3);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  padding: 5px 8px;
  font-size: 11.5px;
  pointer-events: none;
  white-space: nowrap;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
}
.chart__tip b { font-family: var(--mono); font-variant-numeric: tabular-nums; font-weight: 600; }
.chart__tip span { color: var(--text-faint); }

/* ── Filters ───────────────────────────────────────────────────────────── */

.filters { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.chips { display: flex; gap: 4px; flex-wrap: wrap; }

.chip {
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--text-dim);
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 11.5px; font-weight: 550;
  cursor: pointer;
  display: inline-flex; align-items: center; gap: 6px;
}
.chip:hover { border-color: var(--line-strong); color: var(--text); }
.chip[aria-pressed="true"] {
  background: var(--accent-soft);
  border-color: var(--accent-line);
  color: var(--text);
}
.chip__dot { width: 6px; height: 6px; border-radius: 50%; }
.chip__n { font-family: var(--mono); font-size: 10.5px; color: var(--text-faint); }

.field { display: inline-flex; align-items: center; gap: 6px; }
.field__label { font-size: 11px; color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.06em; }
.control {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 4px 6px;
  font-size: 12px;
  max-width: 150px;
}
.control:hover { border-color: var(--line-strong); }

/* ── Incident table ────────────────────────────────────────────────────── */

.table-wrap { min-width: 0; }
.table { width: 100%; border-collapse: collapse; table-layout: fixed; }

.table thead th {
  text-align: left;
  font-size: 10.5px; font-weight: 600;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--text-faint);
  border-bottom: 1px solid var(--line-strong);
  padding: 0 8px 6px;
}
.th-btn {
  background: none; border: 0; padding: 0;
  font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit;
  cursor: pointer; display: inline-flex; align-items: center; gap: 4px;
}
.th-btn:hover { color: var(--text); }
.th-btn::after { content: ""; width: 0; height: 0; border: 3px solid transparent; opacity: 0.7; }
th[aria-sort="ascending"] .th-btn::after  { border-bottom-color: var(--accent); border-top-width: 0; margin-bottom: 2px; }
th[aria-sort="descending"] .th-btn::after { border-top-color: var(--accent); border-bottom-width: 0; margin-top: 2px; }
th[aria-sort]:not([aria-sort="none"]) .th-btn { color: var(--text); }

.col-id      { width: 92px; }
.col-sev     { width: 96px; }
.col-service { width: 128px; }
.col-age     { width: 78px; }
.col-owner   { width: 112px; }
.col-status  { width: 118px; }
.col-title   { width: auto; }
.num-col { text-align: right; }
.num-col .th-btn { justify-content: flex-end; width: 100%; }

.table tbody tr {
  border-bottom: 1px solid var(--line);
  cursor: pointer;
  transition: background 80ms linear;
}
.table tbody tr:hover { background: var(--surface-2); }
.table tbody tr.is-selected { background: var(--accent-soft); box-shadow: inset 2px 0 0 var(--accent); }
.table tbody tr:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

.table td {
  padding: 7px 8px;
  font-size: 12.5px;
  color: var(--text-dim);
  vertical-align: middle;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.table td.col-id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); }
.table td.col-age { font-family: var(--mono); font-variant-numeric: tabular-nums; text-align: right; color: var(--text); }
.table td.col-title { color: var(--text); }
.table td.col-service { font-family: var(--mono); font-size: 11.5px; }
.table td.col-owner { font-size: 12px; }
.owner--none { color: var(--text-faint); font-style: italic; }

.sev {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase;
}
.sev__dot { width: 7px; height: 7px; border-radius: 2px; flex: none; }
.sev--critical { color: var(--crit); } .sev--critical .sev__dot { background: var(--crit); }
.sev--high     { color: var(--high); } .sev--high     .sev__dot { background: var(--high); }
.sev--medium   { color: var(--med);  } .sev--medium   .sev__dot { background: var(--med); }
.sev--low      { color: var(--low);  } .sev--low      .sev__dot { background: var(--low); }

.status {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11.5px; color: var(--text-dim);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  padding: 1px 8px 1px 6px;
  background: var(--surface-2);
}
.status__dot { width: 6px; height: 6px; border-radius: 50%; background: var(--text-faint); flex: none; }
.status--investigating .status__dot { background: var(--accent); }
.status--open          .status__dot { background: var(--high); }
.status--monitoring    .status__dot { background: var(--med); }
.status--acknowledged  .status__dot { background: var(--ok); }
.status--resolved      .status__dot { background: var(--low); }

/* ── Empty state ───────────────────────────────────────────────────────── */

.empty {
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-lg);
  padding: 26px 18px;
  text-align: center;
  margin-top: 2px;
}
.empty__title { font-size: 13px; font-weight: 600; }
.empty__body { font-size: 12px; color: var(--text-faint); margin-top: 4px; }
.empty .btn { margin-top: 12px; }

/* ── Detail panel ──────────────────────────────────────────────────────── */

.detail {
  background: var(--surface);
  border-left: 1px solid var(--line);
  border-top: 1px solid var(--line);
}
.detail__inner { padding: 14px; }

.detail__head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.detail__id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); letter-spacing: 0.02em; }
.detail__title { font-size: 15px; font-weight: 600; line-height: 1.35; margin-top: 4px; }
.detail__badges { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 9px; }

.detail__grid {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  margin-top: 14px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.detail__cell { background: var(--surface-2); padding: 8px 10px; min-width: 0; }
.detail__k { font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); }
.detail__v { font-size: 12.5px; color: var(--text); margin-top: 3px; overflow-wrap: anywhere; }
.detail__v--mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }

.detail__section { margin-top: 16px; }
.detail__section-h {
  font-size: 10.5px; font-weight: 600; letter-spacing: 0.09em; text-transform: uppercase;
  color: var(--text-faint);
  padding-bottom: 6px; border-bottom: 1px solid var(--line);
  margin-bottom: 9px;
}

.timeline { display: flex; flex-direction: column; gap: 0; }
.timeline__item { display: grid; grid-template-columns: 58px 1fr; gap: 10px; padding: 6px 0; }
.timeline__t { font-family: var(--mono); font-size: 11px; color: var(--text-faint); padding-top: 1px; }
.timeline__b { font-size: 12px; color: var(--text-dim); position: relative; padding-left: 12px; }
.timeline__b::before {
  content: ""; position: absolute; left: 0; top: 6px;
  width: 5px; height: 5px; border-radius: 50%; background: var(--line-strong);
}
.timeline__item:first-child .timeline__b::before { background: var(--accent); }
.timeline__item--now .timeline__b { color: var(--text); }

.detail__actions { display: flex; gap: 8px; margin-top: 18px; flex-wrap: wrap; }
.detail__actions .btn { flex: 1 1 auto; }

.detail__note {
  margin-top: 12px; font-size: 11.5px; color: var(--text-faint); line-height: 1.5;
  border-left: 2px solid var(--line-strong); padding-left: 9px;
}

.detail__blank { color: var(--text-faint); font-size: 12.5px; line-height: 1.6; }
.detail__blank strong { display: block; color: var(--text); font-size: 13px; margin-bottom: 4px; }

/* ── Toasts ────────────────────────────────────────────────────────────── */

.toast-stack {
  position: fixed; right: 14px; bottom: 14px; z-index: 50;
  display: flex; flex-direction: column; gap: 8px;
  max-width: min(320px, calc(100vw - 28px));
}
.toast {
  background: var(--surface-3);
  border: 1px solid var(--line-strong);
  border-left: 2px solid var(--accent);
  border-radius: var(--radius);
  padding: 9px 12px;
  font-size: 12px;
  color: var(--text);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.5);
  animation: toast-in 140ms ease-out;
}
.toast--warn { border-left-color: var(--high); }
@keyframes toast-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .toast { animation: none; } }

/* ── Responsive ────────────────────────────────────────────────────────── */

/* Detail panel drops below the main column. */
@media (max-width: 1180px) {
  .app {
    grid-template-columns: var(--rail-w) minmax(0, 1fr);
    grid-template-rows: var(--topbar-h) minmax(0, 1fr);
    grid-template-areas:
      "rail  topbar"
      "rail  main"
      "rail  detail";
    height: auto;
    min-height: 100vh;
  }
  .main, .detail { overflow: visible; }
  .detail {
    border-left: 0; border-top: 1px solid var(--line);
    background: var(--bg);
  }
  .detail__inner { padding: 16px; }
}

@media (max-width: 980px) {
  .metrics__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .col-owner { display: none; }
}

/* Mobile: rail becomes a horizontal strip, single column, no page scroll on x. */
@media (max-width: 760px) {
  .app {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto auto auto;
    grid-template-areas:
      "topbar"
      "rail"
      "main"
      "detail";
  }
  .topbar { height: auto; padding: 8px 12px; flex-wrap: wrap; row-gap: 8px; }
  .topbar__left { width: 100%; }
  .topbar__right { width: 100%; justify-content: space-between; gap: 8px; }
  .search__input { width: 100%; max-width: none; flex: 1 1 120px; }
  .search { flex: 1 1 140px; }
  .who__name { display: none; }
  .who { padding-left: 8px; }

  .rail {
    flex-direction: row; align-items: center; gap: 4px;
    border-right: 0; border-bottom: 1px solid var(--line);
    padding: 6px 12px;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .rail::-webkit-scrollbar { display: none; }
  .rail__brand { padding: 0 8px 0 0; border-right: 1px solid var(--line); margin-right: 4px; }
  .rail__nav { flex-direction: row; gap: 4px; }
  .rail__link { white-space: nowrap; padding: 5px 9px; }
  .rail__foot { display: none; }

  .main { padding: 12px 12px 24px; gap: 12px; }
  .panel { padding: 11px 12px 12px; }
  .table td, .table thead th { padding-left: 6px; padding-right: 6px; }
  .col-service { display: none; }
  .col-id { width: 84px; }
  .col-sev { width: 74px; }
  .col-age { width: 66px; }
  .col-status { width: 104px; }
  .table { table-layout: auto; }
  .filters { width: 100%; }
  .field { flex: 1 1 120px; }
  .control { max-width: none; width: 100%; }
  .field__label { display: none; }
  .toast-stack { right: 12px; left: 12px; bottom: 12px; max-width: none; }
}

/* 390px and below: two-across metrics tighten, ID column hides to protect the
   incident title, which is the only column that must stay readable. */
@media (max-width: 430px) {
  .metrics__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .metric { padding: 9px 10px 10px; }
  .metric__value { font-size: 18px; }
  .col-id { display: none; }
  .col-status { width: 96px; }
  .topbar__meta { display: none; }
  .detail__grid { grid-template-columns: minmax(0, 1fr); }
  .chip { padding: 3px 8px; }
}

input.old_string:
.chart__bar { fill: #35485c; transition: fill 90ms linear; }
.chart__bar--peak { fill: var(--accent); }
.chart__hit { fill: transparent; cursor: crosshair; }
.chart__hit:hover + .chart__bar,
.chart__hit:focus-visible + .chart__bar { fill: var(--accent); }
.chart__hit:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

input.new_string:
.chart__bar { fill: #35485c; transition: fill 90ms linear; }
.chart__bar--peak { fill: var(--accent); }
.chart__bar.is-hot { fill: var(--accent); }
.chart__hit { fill: transparent; cursor: crosshair; }

input.content:
/* ==========================================================================
   Relay — operations control room
   Vanilla JS, no dependencies, no network. Seed data mirrors DATA.json; it is
   inlined so the page also works when opened straight from the filesystem
   (file:// blocks fetch of local JSON).
   ========================================================================== */
(function () {
  'use strict';

  /* ── Seed ─────────────────────────────────────────────────────────────── */

  var DATA = {
    metrics: [
      { label: 'Events / min', value: '18,420', change: '+8.2%', direction: 'up' },
      { label: 'P95 latency', value: '184 ms', change: '−12 ms', direction: 'down' },
      { label: 'Error rate', value: '0.37%', change: '+0.08 pp', direction: 'up' },
      { label: 'Queue depth', value: '2,841', change: '−19%', direction: 'down' }
    ],
    throughput: [31, 28, 24, 22, 20, 23, 34, 48, 62, 71, 76, 73, 68, 72, 80, 84, 79, 75, 82, 88, 77, 63, 52, 41],
    incidents: [
      { id: 'INC-2841', severity: 'critical', service: 'payments-api', age: '12m', owner: 'M. Chen', status: 'investigating', title: 'Card authorization timeouts' },
      { id: 'INC-2839', severity: 'high', service: 'event-router', age: '31m', owner: 'Unassigned', status: 'open', title: 'EU retry queue growth' },
      { id: 'INC-2837', severity: 'medium', service: 'search-index', age: '1h 08m', owner: 'A. Silva', status: 'monitoring', title: 'Index freshness outside SLO' },
      { id: 'INC-2832', severity: 'low', service: 'webhooks', age: '3h 42m', owner: 'R. Patel', status: 'open', title: 'Elevated partner delivery lag' }
    ]
  };

  /* Which direction counts as improvement, per metric. Throughput up is good;
     latency, errors and queue depth improving means going down. */
  var GOOD_DIRECTION = {
    'Events / min': 'up',
    'P95 latency': 'down',
    'Error rate': 'down',
    'Queue depth': 'down'
  };

  var SEVERITY_RANK = { critical: 0, high: 1, medium: 2, low: 3 };
  var SEVERITIES = ['critical', 'high', 'medium', 'low'];
  var STATUSES = ['open', 'investigating', 'monitoring', 'acknowledged', 'resolved'];
  var OPERATOR = 'A. Reyes';
  var SVG_NS = 'http://www.w3.org/2000/svg';

  /* ── State ────────────────────────────────────────────────────────────── */

  var incidents = DATA.incidents.map(function (inc) {
    return Object.assign({}, inc, { ack: null, snooze: null });
  });

  var state = {
    severity: 'all',
    service: 'all',
    status: 'all',
    query: '',
    selectedId: incidents[0] ? incidents[0].id : null,
    sortKey: 'severity',
    sortDir: 'asc',
    live: true
  };

  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };

  /* ── Derived helpers ──────────────────────────────────────────────────── */

  function ageToMinutes(age) {
    var h = /(\d+)\s*h/.exec(age);
    var m = /(\d+)\s*m/.exec(age);
    return (h ? parseInt(h[1], 10) * 60 : 0) + (m ? parseInt(m[1], 10) : 0);
  }

  function ageLabel(minutes) {
    if (minutes < 60) return minutes + 'm';
    var h = Math.floor(minutes / 60);
    var m = minutes % 60;
    return h + 'h ' + (m < 10 ? '0' : '') + m + 'm';
  }

  function detectedAt(inc) {
    return new Date(Date.now() - ageToMinutes(inc.age) * 60000);
  }

  function hhmm(date) {
    return String(date.getUTCHours()).padStart(2, '0') + ':' + String(date.getUTCMinutes()).padStart(2, '0');
  }

  function titleCase(s) { return s.charAt(0).toUpperCase() + s.slice(1); }

  function visibleIncidents() {
    var q = state.query.trim().toLowerCase();
    var rows = incidents.filter(function (inc) {
      if (state.severity !== 'all' && inc.severity !== state.severity) return false;
      if (state.service !== 'all' && inc.service !== state.service) return false;
      if (state.status !== 'all' && inc.status !== state.status) return false;
      if (!q) return true;
      return [inc.id, inc.title, inc.service, inc.owner, inc.severity, inc.status]
        .join(' ').toLowerCase().indexOf(q) !== -1;
    });

    var key = state.sortKey;
    var dir = state.sortDir === 'asc' ? 1 : -1;
    return rows.sort(function (a, b) {
      var av, bv;
      if (key === 'age') { av = ageToMinutes(a.age); bv = ageToMinutes(b.age); }
      else if (key === 'severity') { av = SEVERITY_RANK[a.severity]; bv = SEVERITY_RANK[b.severity]; }
      else { av = String(a[key]).toLowerCase(); bv = String(b[key]).toLowerCase(); }
      if (av < bv) return -1 * dir;
      if (av > bv) return 1 * dir;
      return a.id < b.id ? -1 : 1;
    });
  }

  function announce(msg) { $('live-region').textContent = msg; }

  function toast(msg, kind) {
    var el = document.createElement('div');
    el.className = 'toast' + (kind === 'warn' ? ' toast--warn' : '');
    el.textContent = msg;
    $('toast-stack').appendChild(el);
    window.setTimeout(function () { el.remove(); }, 2800);
  }

  /* ── Metrics ──────────────────────────────────────────────────────────── */

  function renderMetrics() {
    $('metric-list').innerHTML = DATA.metrics.map(function (m) {
      var good = m.direction === GOOD_DIRECTION[m.label];
      var tone = good ? 'good' : 'bad';
      var arrow = m.direction === 'up' ? '▲' : '▼';
      var label = m.label + ': ' + m.value + ', ' +
        (m.direction === 'up' ? 'up' : 'down') + ' ' + m.change + ' versus previous hour, ' +
        (good ? 'improving' : 'worsening');
      return '<li class="metric metric--' + tone + '">' +
          '<div class="metric__label">' + esc(m.label) + '</div>' +
          '<div class="metric__value num" aria-label="' + esc(label) + '">' + esc(m.value) + '</div>' +
          '<div class="metric__foot">' +
            '<span class="metric__delta metric__delta--' + tone + '">' +
              '<span class="metric__arrow" aria-hidden="true">' + arrow + '</span>' + esc(m.change) +
            '</span>' +
            '<span class="metric__ctx">vs. prev hour</span>' +
          '</div>' +
        '</li>';
    }).join('');
  }

  /* ── Throughput chart (inline SVG) ────────────────────────────────────── */

  function svgEl(tag, attrs) {
    var el = document.createElementNS(SVG_NS, tag);
    Object.keys(attrs || {}).forEach(function (k) { el.setAttribute(k, attrs[k]); });
    return el;
  }

  function renderChart() {
    var values = DATA.throughput;
    var W = 720, H = 200, padL = 38, padR = 10, padT = 12, padB = 26;
    var plotW = W - padL - padR;
    var plotH = H - padT - padB;
    var step = plotW / values.length;
    var barW = Math.max(6, step * 0.6);

    var rawMax = Math.max.apply(null, values);
    var max = Math.ceil(rawMax / 10) * 10;
    var ticks = [0, max / 3, (2 * max) / 3, max];
    var yOf = function (v) { return padT + plotH - (v / max) * plotH; };

    var svg = svgEl('svg', {
      viewBox: '0 0 ' + W + ' ' + H,
      width: W, height: H,
      role: 'img',
      'aria-labelledby': 'chart-caption',
      preserveAspectRatio: 'xMidYMid meet'
    });

    ticks.forEach(function (t) {
      var y = Math.round(yOf(t)) + 0.5;
      svg.appendChild(svgEl('line', { class: 'chart__grid', x1: padL, x2: W - padR, y1: y, y2: y }));
      var lbl = svgEl('text', { class: 'chart__tick', x: padL - 8, y: y + 3.5, 'text-anchor': 'end' });
      lbl.textContent = Math.round(t);
      svg.appendChild(lbl);
    });

    svg.appendChild(svgEl('line', { class: 'chart__axis', x1: padL, x2: W - padR, y1: padT + plotH + 0.5, y2: padT + plotH + 0.5 }));

    var peakIndex = values.indexOf(rawMax);
    var bars = [];

    values.forEach(function (v, i) {
      var x = padL + i * step + (step - barW) / 2;
      var h = Math.max(1, (v / max) * plotH);
      var y = padT + plotH - h;
      var bar = svgEl('rect', {
        class: 'chart__bar' + (i === peakIndex ? ' chart__bar--peak' : ''),
        x: x.toFixed(2), y: y.toFixed(2),
        width: barW.toFixed(2), height: h.toFixed(2),
        rx: 1
      });
      svg.appendChild(bar);
      bars.push(bar);

      if (i % 3 === 0) {
        var tl = svgEl('text', { class: 'chart__tick', x: (padL + i * step + step / 2).toFixed(2), y: H - 9, 'text-anchor': 'middle' });
        tl.textContent = String(i).padStart(2, '0');
        svg.appendChild(tl);
      }

      var hit = svgEl('rect', {
        class: 'chart__hit',
        x: (padL + i * step).toFixed(2), y: padT,
        width: step.toFixed(2), height: plotH,
        'data-i': i
      });
      svg.appendChild(hit);
    });

    var nowX = padL + plotW - 0.5;
    svg.appendChild(svgEl('line', { class: 'chart__now', x1: nowX, x2: nowX, y1: padT, y2: padT + plotH }));

    $('chart-plot').innerHTML = '';
    $('chart-plot').appendChild(svg);

    var pad = function (n) { return String(n).padStart(2, '0'); };
    var sum = values.reduce(function (a, b) { return a + b; }, 0);
    $('throughput-total').textContent = sum.toLocaleString('en-US') + 'k';
    $('throughput-peak').textContent = rawMax + 'k/min';
    $('throughput-peak-hour').textContent = pad(peakIndex) + ':00';
    $('chart-caption').textContent =
      'Throughput for the last 24 hours in thousands of events per minute. ' +
      'Low ' + Math.min.apply(null, values) + ' at ' + pad(values.indexOf(Math.min.apply(null, values))) + ':00, ' +
      'high ' + rawMax + ' at ' + pad(peakIndex) + ':00 UTC.';

    $('chart-table').querySelector('tbody').innerHTML = values.map(function (v, i) {
      return '<tr><th scope="row">' + pad(i) + ':00</th><td>' + v + '</td></tr>';
    }).join('');

    /* Hover readout — pointer only; the sr-only table carries the same data. */
    var plot = $('chart-plot');
    var tip = $('chart-tip');
    plot.addEventListener('mousemove', function (ev) {
      var hit = ev.target.closest ? ev.target.closest('.chart__hit') : null;
      if (!hit) { tip.hidden = true; bars.forEach(function (b) { b.classList.remove('is-hot'); }); return; }
      var i = parseInt(hit.getAttribute('data-i'), 10);
      bars.forEach(function (b, j) { b.classList.toggle('is-hot', j === i); });
      var r = plot.getBoundingClientRect();
      tip.innerHTML = '<b>' + values[i] + 'k/min</b> <span>· ' + pad(i) + ':00–' + pad((i + 1) % 24) + ':00</span>';
      tip.hidden = false;
      tip.style.left = Math.min(Math.max(ev.clientX - r.left, 34), r.width - 34) + 'px';
      tip.style.top = (ev.clientY - r.top - 10) + 'px';
    });
    plot.addEventListener('mouseleave', function () {
      tip.hidden = true;
      bars.forEach(function (b) { b.classList.remove('is-hot'); });
    });
  }

  /* ── Filters ──────────────────────────────────────────────────────────── */

  function renderFilterControls() {
    var counts = {};
    incidents.forEach(function (inc) { counts[inc.severity] = (counts[inc.severity] || 0) + 1; });

    $('severity-chips').innerHTML =
      '<button type="button" class="chip" data-severity="all" aria-pressed="' + (state.severity === 'all') + '">' +
        'All <span class="chip__n">' + incidents.length + '</span></button>' +
      SEVERITIES.map(function (s) {
        return '<button type="button" class="chip" data-severity="' + s + '" aria-pressed="' + (state.severity === s) + '">' +
          '<span class="chip__dot" aria-hidden="true" style="background:var(--' + (s === 'critical' ? 'crit' : s === 'high' ? 'high' : s === 'medium' ? 'med' : 'low') + ')"></span>' +
          titleCase(s) + ' <span class="chip__n">' + (counts[s] || 0) + '</span></button>';
      }).join('');

    var services = incidents.map(function (i) { return i.service; })
      .filter(function (v, i, a) { return a.indexOf(v) === i; }).sort();
    var activeServices = incidents.map(function (i) { return i.service; });
    fillSelect($('filter-service'), services, 'All services', state.service);
    fillSelect($('filter-status'),
      STATUSES.filter(function (s) { return activeServices.length && (s !== 'resolved' || incidents.some(function (i) { return i.status === s; })); }),
      'Any status', state.status);
  }

  function fillSelect(sel, values, allLabel, current) {
    sel.innerHTML = '<option value="all">' + esc(allLabel) + '</option>' +
      values.map(function (v) {
        return '<option value="' + esc(v) + '"' + (v === current ? ' selected' : '') + '>' + esc(titleCase(v.replace(/-/g, ' '))) + '</option>';
      }).join('');
  }

  /* ── Table ────────────────────────────────────────────────────────────── */

  function renderTable() {
    var rows = visibleIncidents();
    var body = $('incident-body');

    $('result-count').textContent = rows.length;
    $('total-count').textContent = incidents.length;
    $('rail-count').textContent = incidents.filter(function (i) { return i.status !== 'resolved'; }).length;
    $('empty-state').hidden = rows.length !== 0;
    $('incident-table').hidden = rows.length === 0;

    body.innerHTML = rows.map(function (inc) {
      var selected = inc.id === state.selectedId;
      var unowned = inc.owner === 'Unassigned';
      return '<tr tabindex="0" data-id="' + esc(inc.id) + '"' +
          ' class="' + (selected ? 'is-selected' : '') + '"' +
          (selected ? ' aria-current="true"' : '') + '>' +
        '<td class="col-id">' + esc(inc.id) + '</td>' +
        '<td class="col-sev"><span class="sev sev--' + inc.severity + '"><span class="sev__dot" aria-hidden="true"></span>' + esc(inc.severity) + '</span></td>' +
        '<td class="col-title" title="' + esc(inc.title) + '">' + esc(inc.title) + '</td>' +
        '<td class="col-service">' + esc(inc.service) + '</td>' +
        '<td class="col-age num-col">' + esc(inc.age) + '</td>' +
        '<td class="col-owner' + (unowned ? ' owner--none' : '') + '">' + esc(inc.owner) + '</td>' +
        '<td class="col-status"><span class="status status--' + inc.status + '"><span class="status__dot" aria-hidden="true"></span>' + esc(inc.status) + '</span></td>' +
      '</tr>';
    }).join('');

    document.querySelectorAll('#incident-table th').forEach(function (th) {
      var btn = th.querySelector('.th-btn');
      if (!btn) return;
      th.setAttribute('aria-sort', btn.getAttribute('data-sort') === state.sortKey
        ? (state.sortDir === 'asc' ? 'ascending' : 'descending')
        : 'none');
    });
  }

  function renderDetail() {
    var host = $('detail-body');
    var inc = incidents.filter(function (i) { return i.id === state.selectedId; })[0];

    if (!inc) {
      host.innerHTML =
        '<div class="detail__blank"><strong>No incident selected</strong>' +
        'Pick a row in the incident table to see ownership, timing, and the action set. ' +
        'Use <kbd>j</kbd> and <kbd>k</kbd> to move through the queue.</div>';
      return;
    }

    var detected = detectedAt(inc);
    var minutes = ageToMinutes(inc.age);
    var events = [
      { t: hhmm(detected), text: 'Alert fired on ' + inc.service + ' — ' + inc.title, now: true }
    ];
    if (inc.owner !== 'Unassigned') {
      events.push({ t: hhmm(new Date(detected.getTime() + 2 * 60000)), text: 'Auto-routed to ' + inc.owner });
    } else {
      events.push({ t: hhmm(new Date(detected.getTime() + 2 * 60000)), text: 'No primary owner matched — awaiting assignment' });
    }
    if (inc.status !== 'open') {
      events.push({ t: hhmm(new Date(detected.getTime() + Math.max(4, Math.round(minutes * 0.3)) * 60000)), text: 'Status set to ' + inc.status });
    }
    if (inc.ack) {
      events.push({ t: inc.ack.time, text: 'Acknowledged by ' + inc.ack.by });
    }

    var acked = !!inc.ack;

    host.innerHTML =
      '<div class="detail__head">' +
        '<div><div class="detail__id">' + esc(inc.id) + '</div>' +
        '<h2 class="detail__title" id="detail-title">' + esc(inc.title) + '</h2></div>' +
      '</div>' +
      '<div class="detail__badges">' +
        '<span class="sev sev--' + inc.severity + '"><span class="sev__dot" aria-hidden="true"></span>' + esc(inc.severity) + '</span>' +
        '<span class="status status--' + inc.status + '"><span class="status__dot" aria-hidden="true"></span>' + esc(inc.status) + '</span>' +
      '</div>' +

      '<div class="detail__grid">' +
        cell('Service', inc.service, true) +
        cell('Owner', inc.owner) +
        cell('Age', inc.age, true) +
        cell('Detected', hhmm(detected) + ' UTC', true) +
      '</div>' +

      '<div class="detail__section">' +
        '<h3 class="detail__section-h">Activity</h3>' +
        '<ol class="timeline">' + events.map(function (e) {
          return '<li class="timeline__item"><span class="timeline__t">' + esc(e.t) + '</span>' +
            '<span class="timeline__b">' + esc(e.text) + '</span></li>';
        }).join('') + '</ol>' +
      '</div>' +

      '<div class="detail__actions">' +
        '<button type="button" class="btn btn--primary" id="ack-btn"' + (acked ? ' disabled' : '') + '>' +
          (acked ? 'Acknowledged' : 'Acknowledge') + '</button>' +
        '<button type="button" class="btn btn--secondary" id="copy-btn">Copy ID</button>' +
      '</div>' +

      '<p class="detail__note">' + esc(noteFor(inc)) + '</p>';

    var ackBtn = $('ack-btn');
    if (ackBtn) {
      ackBtn.addEventListener('click', function () { acknowledge(inc.id); });
    }
    $('copy-btn').addEventListener('click', function () {
      copyText(inc.id);
      toast('Copied ' + inc.id);
      announce('Incident ID ' + inc.id + ' copied');
    });
  }

  function cell(k, v, mono) {
    return '<div class="detail__cell"><div class="detail__k">' + esc(k) + '</div>' +
      '<div class="detail__v' + (mono ? ' detail__v--mono' : '') + '">' + esc(v) + '</div></div>';
  }

  function noteFor(inc) {
    if (inc.severity === 'critical') return 'Critical incidents page the secondary on-call after 15 minutes without acknowledgement.';
    if (inc.severity === 'high') return 'High severity work is tracked on the incident channel until acknowledged.';
    if (inc.severity === 'medium') return 'Medium severity incidents are reviewed at the next shift handover.';
    return 'Low severity incidents auto-resolve after 24h without further errors.';
  }

  /* ── Actions ──────────────────────────────────────────────────────────── */

  function acknowledge(id) {
    var inc = incidents.filter(function (i) { return i.id === id; })[0];
    if (!inc || inc.ack) return;
    inc.ack = { by: OPERATOR, time: hhmm(new Date()) };
    inc.status = 'acknowledged';
    renderTable();
    renderDetail();
    toast(inc.id + ' acknowledged by ' + OPERATOR);
    announce(inc.id + ' acknowledged. Status is now acknowledged.');
  }

  function copyText(text) {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text);
        return;
      }
    } catch (e) { /* clipboard unavailable (file://, permissions) — fall through */ }
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) { /* ignore */ }
    ta.remove();
  }

  function selectIncident(id, opts) {
    state.selectedId = id;
    renderTable();
    renderDetail();
    if (opts && opts.focusPanel) $('detail-panel').focus();
  }

  function moveSelection(delta) {
    var rows = Array.prototype.slice.call(document.querySelectorAll('#incident-body tr'));
    if (!rows.length) return;
    var idx = rows.findIndex(function (r) { return r.getAttribute('data-id') === state.selectedId; });
    var next = rows[(idx + delta + rows.length) % rows.length];
    selectIncident(next.getAttribute('data-id'));
    var focusRow = document.querySelector('#incident-body tr[data-id="' + next.getAttribute('data-id') + '"]');
    if (focusRow) focusRow.focus();
  }

  /* ── Wiring ───────────────────────────────────────────────────────────── */

  function render() {
    renderTable();
    renderDetail();
  }

  function bind() {
    $('severity-chips').addEventListener('click', function (ev) {
      var chip = ev.target.closest('.chip');
      if (!chip) return;
      state.severity = chip.getAttribute('data-severity');
      renderFilterControls();
      renderTable();
      announce(incidents.length + ' incidents, ' + visibleIncidents().length + ' shown');
    });

    $('filter-service').addEventListener('change', function (e) {
      state.service = e.target.value;
      renderTable();
    });
    $('filter-status').addEventListener('change', function (e) {
      state.status = e.target.value;
      renderTable();
    });
    $('global-search').addEventListener('input', function (e) {
      state.query = e.target.value;
      renderTable();
    });
    $('clear-filters').addEventListener('click', function () {
      state.severity = 'all'; state.service = 'all'; state.status = 'all'; state.query = '';
      $('global-search').value = '';
      renderFilterControls();
      renderTable();
      announce('Filters cleared');
    });

    document.querySelectorAll('.th-btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var key = btn.getAttribute('data-sort');
        if (state.sortKey === key) {
          state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
        } else {
          state.sortKey = key;
          state.sortDir = (key === 'age' || key === 'severity') ? 'asc' : 'asc';
        }
        renderTable();
      });
    });

    var body = $('incident-body');
    body.addEventListener('click', function (ev) {
      var row = ev.target.closest('tr[data-id]');
      if (row) selectIncident(row.getAttribute('data-id'));
    });
    body.addEventListener('keydown', function (ev) {
      var row = ev.target.closest('tr[data-id]');
      if (!row) return;
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        selectIncident(row.getAttribute('data-id'), { focusPanel: true });
      } else if (ev.key === 'ArrowDown' || ev.key === 'j') {
        ev.preventDefault(); moveSelection(1);
      } else if (ev.key === 'ArrowUp' || ev.key === 'k') {
        ev.preventDefault(); moveSelection(-1);
      }
    });

    document.addEventListener('keydown', function (ev) {
      var tag = (ev.target.tagName || '').toLowerCase();
      var typing = tag === 'input' || tag === 'select' || tag === 'textarea';
      if (ev.key === '/' && !typing) {
        ev.preventDefault();
        $('global-search').focus();
        $('global-search').select();
      } else if (ev.key === 'Escape' && ev.target === $('global-search')) {
        $('global-search').value = '';
        state.query = '';
        renderTable();
      } else if (!typing && (ev.key === 'j' || ev.key === 'k') && document.activeElement === document.body) {
        ev.preventDefault();
        moveSelection(ev.key === 'j' ? 1 : -1);
      }
    });

    $('live-toggle').addEventListener('click', function () {
      state.live = !state.live;
      var btn = this;
      btn.setAttribute('aria-pressed', String(state.live));
      $('live-label').textContent = state.live ? 'Live' : 'Paused';
      $('live-dot').className = 'dot ' + (state.live ? 'dot--live' : 'dot--paused');
      announce(state.live ? 'Live updates resumed' : 'Live updates paused');
    });

    $('rail-nav').addEventListener('click', function (ev) {
      var link = ev.target.closest('.rail__link');
      if (!link) return;
      $('rail-nav').querySelectorAll('.rail__link').forEach(function (l) {
        var on = l === link;
        l.classList.toggle('is-current', on);
        if (on) { l.setAttribute('aria-current', 'page'); } else { l.removeAttribute('aria-current'); }
      });
    });
  }

  function startClock() {
    var tick = function () {
      if (!state.live) return;
      var d = new Date();
      $('clock').textContent = hhmm(d) + ':' + String(d.getUTCSeconds()).padStart(2, '0');
    };
    tick();
    window.setInterval(tick, 1000);
  }

  renderMetrics();
  renderChart();
  renderFilterControls();
  render();
  bind();
  startClock();
})();

