const fs = require('fs');

function el(tag, attrs = {}) {
  const node = {
    tagName: (tag || 'div').toUpperCase(),
    children: [], attrs: { ...attrs }, listeners: {},
    textContent: '', _html: '', hidden: false, className: '', value: '',
    style: {},
    classList: {
      _s: new Set(),
      add(c) { this._s.add(c); }, remove(c) { this._s.delete(c); },
      toggle(c, on) { on ? this._s.add(c) : this._s.delete(c); },
      contains(c) { return this._s.has(c); }
    },
    setAttribute(k, v) { node.attrs[k] = String(v); },
    getAttribute(k) { return k in node.attrs ? node.attrs[k] : null; },
    removeAttribute(k) { delete node.attrs[k]; },
    appendChild(c) { node.children.push(c); return c; },
    remove() {},
    focus() { doc.activeElement = node; },
    select() {},
    getBoundingClientRect() { return { left: 0, top: 0, width: 700, height: 200 }; },
    addEventListener(type, fn) { (node.listeners[type] = node.listeners[type] || []).push(fn); },
    closest(sel) { return node._closest ? node._closest(sel) : null; },
    querySelector(sel) { return node._q ? node._q(sel) : null; },
    querySelectorAll(sel) { return node._qa ? node._qa(sel) : []; },
    fire(type, ev) { (node.listeners[type] || []).forEach(fn => fn(ev)); },
    get innerHTML() { return node._html; },
    set innerHTML(v) { node._html = String(v); node.children = []; }
  };
  return node;
}

const ids = {};
function byId(id) {
  if (!ids[id]) ids[id] = el('div', { id });
  return ids[id];
}

