    if (sel === '.th-btn') return thBtns;
    if (sel === '#incident-body tr') return [el('tr', { 'data-id': 'INC-2841' })];
    if (sel === '.rail__link') return railLinks;
    if (sel.startsWith('#incident-body tr[data-id')) return [el('tr', { 'data-id': 'INC-2841' })];
    return [];
  },
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; },
  addEventListener(type, fn) { (doc._l = doc._l || {})[type] = (doc._l[type] || []).concat(fn); },
  execCommand() {}
};
