const checks = [
  ['metrics rendered', /metric__value/.test(ids['metric-list'].innerHTML)],
  ['4 metric cards', (ids['metric-list'].innerHTML.match(/class="metric /g) || []).length === 4],
  ['chart svg built', ids['chart-plot'].children.length === 1],
  ['chart bars = 24', (ids['chart-plot'].children[0].children.filter(c => c.attrs.class === 'chart__bar' || (c.attrs.class || '').indexOf('chart__bar--peak') > -1).length) === 24],
  ['chart caption', /high 88 at 19:00/.test(ids['chart-caption'].textContent)],
  ['4 incidents listed', (rowHtml.match(/<tr /g) || []).length === 4],
  ['severity sort: critical first', rowHtml.indexOf('INC-2841') < rowHtml.indexOf('INC-2832')],
  ['selected row marked', /is-selected/.test(rowHtml)],
  ['count text', ids['result-count'].textContent === '4' && ids['total-count'].textContent === '4'],
  ['empty state hidden', ids['empty-state'].hidden === false],
  ['detail rendered', /Card authorization timeouts/.test(ids['detail-body'].innerHTML)],
